<script setup lang="ts">
import {computed,ref,defineAsyncComponent} from 'vue'
import type {Run} from '../types'
import catalog from '../stepCatalog.json'
import {errorSummary,dateTime} from '../uiHelpers'
import {state} from '../store'
import AppIcon from './AppIcon.vue'
import PerformanceReport from './PerformanceReport.vue'
import StatusBadge from './StatusBadge.vue'
import NetworkPanel from './NetworkPanel.vue'
const CodeEditor=defineAsyncComponent(()=>import('./CodeEditor.vue'))
const props=defineProps<{run:Run}>()
const tab=ref('summary'),sourceStep=ref('')
const item=computed(()=>state.cases.find(c=>c.id===props.run.caseId))
const mapping=computed(()=>item.value?.revisions.find(r=>r.number===props.run.revision)?.stepMap||[])
const highlighted=computed(()=>mapping.value.find(s=>s.id===sourceStep.value))
const code=computed(()=>item.value?.revisions.find(r=>r.number===props.run.revision)?.code??'')
function stepTitle(step:{name:string;action:string}){if(!step.name||/^步骤\s*\d+$/.test(step.name))return catalog[props.run.kind||item.value?.kind||'api'].find(action=>action.action===step.action)?.label||step.name||'步骤';return step.name}
const failures=['failed','error','timed_out','interrupted']
const failedStep=computed(()=>props.run.steps?.find(step=>failures.includes(step.status)))
const failureReason=computed(()=>{const error=failedStep.value?.error||props.run.collectionErrors?.[0]||props.run.items.find(item=>item.error)?.error;return error?errorSummary(error):props.run.summary})
const evidence=computed(()=>props.run.artifacts.filter(a=>/\.(png|jpe?g|webp|webm|mp4)$/i.test(a.name)))
</script>
<template><section class="run-report"><div class="report-heading"><div><h2>{{item?.name??run.caseId}}</h2><span class="overline mono">{{run.id}}</span></div><StatusBadge :status="run.status"/></div><div class="report-meta"><span>版本 v{{run.revision}}</span><span>{{run.environment}}</span><span>{{dateTime(run.createdAt)}}</span><span>耗时 {{run.duration}}</span></div><div class="local-tabs" role="tablist" aria-label="报告内容"><button v-for="entry in [{id:'summary',label:'结果与证据'},{id:'logs',label:'执行日志'},...(run.network?[{id:'network',label:'网络请求'}]:[]),{id:'code',label:'执行源码'}]" :key="entry.id" role="tab" :aria-selected="tab===entry.id" :class="{active:tab===entry.id}" @click="tab=entry.id">{{entry.label}}</button></div>
<div v-if="tab==='summary'" class="report-content"><div class="failure-callout" :class="run.status"><AppIcon :name="run.status==='passed'?'passed':failures.includes(run.status)?'failed':run.status==='running'?'running':'info'" :size="20"/><div><strong>{{run.summary==='测试断言失败'?'测试未通过':run.summary}}</strong><p v-if="failedStep">失败位置：第 {{failedStep.index}} 步 · {{stepTitle(failedStep)}}</p><p v-else-if="run.status==='running'||run.status==='queued'">报告随执行进度更新。</p></div></div>
<section v-if="failures.includes(run.status)" class="failure-focus"><h3>失败原因</h3><p class="preserve-lines">{{failureReason}}</p><div v-if="failedStep?.expectedStatus" class="comparison"><div><span>预期 HTTP 状态</span><strong>{{failedStep.expectedStatus}}</strong></div><div><span>实际 HTTP 状态</span><strong>{{failedStep.httpStatus??'请求未完成'}}</strong></div></div><button v-if="failedStep?.sourceLine" class="text-button" @click="sourceStep=failedStep.id||'';tab='code'">定位对应源码 L{{failedStep.sourceLine}}</button></section>
<PerformanceReport v-if="run.metrics" :run="run"/>
<section v-if="run.steps?.length" class="report-section"><h3>步骤结果</h3><details v-for="(s,execution) in run.steps" :key="execution" class="report-step" :open="failures.includes(s.status)"><summary><StatusBadge :status="s.status"/><strong>{{s.index}}. {{stepTitle(s)}}</strong><span>{{s.duration??0}}s</span><AppIcon name="down" :size="14"/></summary><div class="report-step-content"><p v-if="s.conditionMatched!==undefined">条件{{s.conditionMatched?'满足，执行条件分支':'不满足，跳过条件分支'}}</p><p v-if="s.httpStatus">响应 HTTP {{s.httpStatus}}<span v-if="s.expectedStatus"> · 预期 {{s.expectedStatus}}</span> · {{s.responseTimeMs}}ms</p><p v-if="s.error" class="inline-error">{{errorSummary(s.error)}}</p><button v-if="s.sourceLine" class="text-button" @click="sourceStep=s.id||'';tab='code'">查看对应源码 L{{s.sourceLine}}</button><details v-if="s.error" class="technical-details"><summary>完整错误记录</summary><pre class="log-block">{{s.error}}</pre></details></div></details></section>
<section v-if="evidence.length" class="report-section"><h3>截图与录制</h3><div class="evidence-gallery"><figure v-for="artifact in evidence" :key="artifact.url"><video v-if="/\.(webm|mp4)$/i.test(artifact.name)" :src="artifact.url" controls preload="metadata"/><a v-else :href="artifact.url" target="_blank" rel="noopener"><img :src="artifact.url" :alt="artifact.name+' · 执行截图'" loading="lazy"/></a><figcaption>{{artifact.name}}</figcaption></figure></div></section>
<details v-if="run.appSnapshot" class="report-section"><summary>应用与设备快照</summary><p>{{run.appSnapshot.name}} · {{run.appSnapshot.version}} · {{run.deviceSnapshot?.name}}</p><p class="mono">{{run.appSnapshot.path?'APK SHA256':'登记信息 SHA256'}}：{{run.appSnapshot.hash}}</p></details>
<details v-if="run.items.length||run.collectionErrors?.length" class="report-section technical-details"><summary>技术详情 · {{run.items.length}} 项测试</summary><article v-for="(result,index) in run.items" :key="index" class="generated-case"><div><div class="case-title-row"><strong class="mono">{{result.nodeid}}</strong><StatusBadge :status="result.outcome==='passed'?'passed':result.outcome==='skipped'?'skipped':'failed'"/></div><p>{{result.phase}} · {{result.duration.toFixed(3)}}s</p><pre v-if="result.error" class="log-block">{{result.error}}</pre></div></article><pre v-for="(error,index) in run.collectionErrors" :key="index" class="log-block">{{error}}</pre></details>
<details class="report-section"><summary>执行配置</summary><p>测试器访问地址：<code>{{run.environmentSnapshot.executionUrl}}</code></p><p class="preserve-lines mono">代码 SHA256：{{run.codeHash}}<br/>运行镜像：{{run.runtimeImage??'未采集'}}</p></details>
<details v-if="run.artifacts.length" class="report-section"><summary>附件 · {{run.artifacts.length}}</summary><div class="artifact-row"><a v-for="artifact in run.artifacts" :key="artifact.name" :href="artifact.url" target="_blank" rel="noopener" class="artifact-button"><AppIcon name="file" :size="17"/><span>{{artifact.name}}<small>{{artifact.size?Math.ceil(artifact.size/1024)+' KB':'查看附件'}}</small></span></a></div><p v-if="run.artifacts.some(a=>a.name.endsWith('-trace.zip'))" class="form-hint">下载 Trace 后使用 playwright show-trace 查看。</p></details></div>
<div v-else-if="tab==='network'&&run.network" class="report-content"><NetworkPanel :session-id="run.network.id"/></div>
<div v-else-if="tab==='logs'" class="report-content"><pre class="log-block">{{run.logs||'等待执行日志写入'}}</pre></div><div v-else><div class="code-filebar">{{item?.filename}}<span>只读 · v{{run.revision}}</span></div><CodeEditor :model-value="code" :highlight="highlighted?.start?{start:highlighted.start,end:highlighted.end!}:undefined" :language="item?.kind==='performance'?'xml':'python'" readonly/></div><div class="report-footer"><span>执行版本 v{{run.revision}}</span><RouterLink :to="`/cases/${run.caseId}?revision=${run.revision}`">查看该版本用例<AppIcon name="external" :size="14"/></RouterLink></div></section></template>
